@libentry()
@triton.jit
def lu_unpack_p_kernel_small(
    pivots_ptr,
    p_ptr,
    m,
    k,
    pivots_stride_b,
    pivots_stride_k,
    p_stride_b,
    p_stride_m,
    p_stride_n,
    BLOCK_M: tl.constexpr,
):
    """
    Vectorized P kernel for small/medium matrices (m <= BLOCK_M).
    One program per batch element processes the entire permutation at once.
    Grid: (batch_size,)

    Strategy: maintain perm[0..m-1] as a vector, apply all k swaps vectorized,
    then scatter 1.0 to P[i, perm[i]] for each i.
    """
    batch_id = tl.program_id(0)

    pivots_base = batch_id * pivots_stride_b
    p_base = batch_id * p_stride_b

    # Initialize perm = [0, 1, 2, ..., m-1]
    row_ids = tl.arange(0, BLOCK_M)
    perm = row_ids  # perm[i] tracks where row i maps to
    mask = row_ids < m

    # Apply all pivot swaps vectorized
    for i in range(k):
        pivot_val = tl.load(pivots_ptr + pivots_base + i * pivots_stride_k)
        pivot_idx = pivot_val - 1  # 0-indexed

        # Vectorized swap: for all rows simultaneously
        # If perm[j] == i, set perm[j] = pivot_idx
        # If perm[j] == pivot_idx, set perm[j] = i
        perm = tl.where(
            perm == i,
            pivot_idx,
            tl.where(perm == pivot_idx, i, perm),
        )

    # Write P[i, perm[i]] = 1.0 for each row i
    # P is pre-zeroed, just scatter the 1s
    offsets = p_base + row_ids * p_stride_m + perm * p_stride_n
    tl.store(p_ptr + offsets, tl.full([BLOCK_M], 1.0, dtype=tl.float32), mask=mask)


@libentry()
@triton.jit
def lu_unpack_p_kernel_large(
    pivots_ptr,
    p_ptr,
    m,
    k,
    pivots_stride_b,
    pivots_stride_k,
    p_stride_b,
    p_stride_m,
    p_stride_n,
    BLOCK_SIZE: tl.constexpr,
):
    """
    P kernel for large matrices (m > 4096).
    Each program handles one row, computes its final permutation position,
    then writes a single 1.0 at P[row, final_pos].
    Grid: (batch_size * m,)
    """
    pid = tl.program_id(0)
    batch_id = pid // m
    row_id = pid % m

    pivots_base = batch_id * pivots_stride_b
    p_base = batch_id * p_stride_b

    # Track where this row ends up after applying all pivot swaps
    current_pos = row_id
    for i in range(k):
        pivot_val = tl.load(pivots_ptr + pivots_base + i * pivots_stride_k)
        pivot_idx = pivot_val - 1
        current_pos = tl.where(
            current_pos == i,
            pivot_idx,
            tl.where(current_pos == pivot_idx, i, current_pos),
        )

    # P is pre-zeroed; only write the single 1.0
    tl.store(
        p_ptr + p_base + row_id * p_stride_m + current_pos * p_stride_n,
        1.0,
    )


@libentry()
@triton.jit
def lu_unpack_l_kernel(
    lu_ptr,
    l_ptr,
    m,
    n,
    k,
    lu_stride_b,
    lu_stride_m,
    lu_stride_n,
    l_stride_b,
    l_stride_m,
    l_stride_n,
    BLOCK_K: tl.constexpr,
):
    """
    Kernel to extract L from packed LU data.
    Each program handles one row of L for one batch element.
    Grid: (batch_size * m,)
    L[row, col] = LU[row, col] if row > col, 1 if row == col, 0 otherwise
    """
    pid = tl.program_id(0)
    batch_id = pid // m
    row = pid % m

    lu_base = batch_id * lu_stride_b
    l_base = batch_id * l_stride_b

    col_offsets = tl.arange(0, BLOCK_K)
    num_blocks = (k + BLOCK_K - 1) // BLOCK_K
    for block_idx in range(num_blocks):
        cols = block_idx * BLOCK_K + col_offsets
        mask = cols < k

        lu_vals = tl.load(
            lu_ptr + lu_base + row * lu_stride_m + cols * lu_stride_n,
            mask=mask,
            other=0.0,
        )

        vals = tl.where(row > cols, lu_vals, tl.where(row == cols, 1.0, 0.0))

        tl.store(
            l_ptr + l_base + row * l_stride_m + cols * l_stride_n,
            vals,
            mask=mask,
        )


