    batch_id = pid // k
    row = pid % k

    lu_base = batch_id * lu_stride_b
    u_base = batch_id * u_stride_b

    col_offsets = tl.arange(0, BLOCK_N)
    num_blocks = (n + BLOCK_N - 1) // BLOCK_N
