def lu_unpack(LU_data, LU_pivots, unpack_data=True, unpack_pivots=True):
    """
    Unpacks the LU decomposition into P, L, U matrices.

    Args:
        LU_data: Tensor of shape (..., m, n) containing the packed LU factorization
        LU_pivots: Tensor of shape (..., min(m, n)) containing the pivots (1-indexed)
        unpack_data: If True, unpack L and U. If False, return empty tensors.
        unpack_pivots: If True, unpack P. If False, return empty tensor.

    Returns:
        Tuple of (P, L, U) where:
            P: (..., m, m) permutation matrix
            L: (..., m, min(m, n)) lower triangular with unit diagonal
            U: (..., min(m, n), n) upper triangular

    This is the forward-only entry used by the device dispatch of
    ``aten::lu_unpack``.  ``torch.lu_unpack`` under ``flag_gems.use_gems()``
    records a graph whose backward is the fused
    :func:`lu_unpack_backward` kernel; only ``L`` and ``U`` are differentiable.
    """
    if torch.is_grad_enabled() and LU_data.requires_grad:
        return LuUnpackFunction.apply(LU_data, LU_pivots, unpack_data, unpack_pivots)
    # Get shapes
    lu_shape = LU_data.shape
    pivots_shape = LU_pivots.shape

    assert LU_data.dtype in (
        torch.float32,
        torch.float64,
    ), f"lu_unpack only supports float32/float64, got {LU_data.dtype}"

    # Handle batch dimensions
    batch_dims = lu_shape[:-2]
    m, n = lu_shape[-2], lu_shape[-1]
    k = min(m, n)  # min(m, n)

    logger.debug(
        "GEMS LU_UNPACK, shape: %s, m: %s, n: %s, k: %s",
        lu_shape,
        m,
        n,
        k,
    )

    # Prepare outputs
    device = LU_data.device
    dtype = LU_data.dtype

    # Handle batch size
    if len(batch_dims) > 0:
        batch_size = 1
        for dim in batch_dims:
            batch_size *= dim
    else:
        batch_size = 1

    if unpack_pivots:
        # P has shape (..., m, m), pre-initialized to zeros
        P = torch.zeros(*batch_dims, m, m, device=device, dtype=dtype)

        # Hybrid strategy based on matrix size:
        # - Small m (<=512): vectorized kernel processing entire perm in one program
        #   (reduces total pivot loop iterations from m*k to k with SIMD width m)
        # - Large m (>512): per-row kernel with single store (better parallelism)
        if m <= 512:
            # Vectorized kernel: one program per batch, processes all rows in parallel
            BLOCK_M = triton.next_power_of_2(m)
            grid = (batch_size,)
            lu_unpack_p_kernel_small[grid](
                LU_pivots,
                P,
                m,
                k,
                LU_pivots.stride(-2) if len(pivots_shape) > 1 else 0,
                LU_pivots.stride(-1) if len(pivots_shape) > 0 else 0,
                P.stride(-3) if len(batch_dims) > 0 else 0,
                P.stride(-2),
                P.stride(-1),
                BLOCK_M,
            )
        else:
            # Per-row kernel: each program tracks one row through pivots
            BLOCK_SIZE = 1  # Each program writes single element
            grid = (batch_size * m,)
            lu_unpack_p_kernel_large[grid](
                LU_pivots,
                P,
                m,
                k,
                LU_pivots.stride(-2) if len(pivots_shape) > 1 else 0,
                LU_pivots.stride(-1) if len(pivots_shape) > 0 else 0,
                P.stride(-3) if len(batch_dims) > 0 else 0,
                P.stride(-2),
                P.stride(-1),
                BLOCK_SIZE,
            )
    else:
        # Return empty tensor
        P = torch.empty(0, device=device, dtype=dtype)

    if unpack_data:
        # L has shape (..., m, k)
        L = torch.empty(*batch_dims, m, k, device=device, dtype=dtype)
        # U has shape (..., k, n)
        U = torch.empty(*batch_dims, k, n, device=device, dtype=dtype)

        # Compute block sizes as next power of 2, capped at 1024
        BLOCK_K = triton.next_power_of_2(k)
        if BLOCK_K > 1024:
            BLOCK_K = 1024
        BLOCK_N = triton.next_power_of_2(n)
        if BLOCK_N > 1024:
            BLOCK_N = 1024

        # Extract L: each program handles one row
        grid_l = (batch_size * m,)
        lu_unpack_l_kernel[grid_l](
            LU_data,
            L,
            m,
            n,
            k,
            LU_data.stride(-3) if len(lu_shape) > 2 else 0,
            LU_data.stride(-2),
            LU_data.stride(-1),
            L.stride(-3) if len(batch_dims) > 0 else 0,
            L.stride(-2),
            L.stride(-1),
            BLOCK_K,
        )

        # Extract U: each program handles one row
        grid_u = (batch_size * k,)
        lu_unpack_u_kernel[grid_u](
            LU_data,
            U,
            m,
            n,
            k,
            LU_data.stride(-3) if len(lu_shape) > 2 else 0,
            LU_data.stride(-2),
            LU_data.stride(-1),
            U.stride(-3) if len(batch_dims) > 0 else 0,
            U.stride(-2),
            U.stride(-1),
            BLOCK_N,
        )
    else:
        # Return empty tensors
        L = torch.empty(0, device=device, dtype=dtype)
        U = torch.empty(0, device=device, dtype=dtype)

    return (P, L, U)


class LuUnpackFunction(torch.autograd.Function):
    """Autograd wrapper around :func:`lu_unpack`.

    The forward keeps the existing unpack kernels; the backward repacks
    ``grad_L`` / ``grad_U`` with the fused :func:`lu_unpack_backward` kernel
    instead of the ``tril`` / ``triu`` / ``add`` / ``cat`` composite that
    ``torch/csrc/autograd/FunctionsManual.cpp`` uses.

    ``P`` and ``LU_pivots`` are non-differentiable, matching the ATen schema
    (``output_differentiability: [False, True, True]``); no gradient is
    fabricated for them.

    Only the gradients of ``L`` and ``U`` exist, and each may be ``None`` when
    that output was unused, so :func:`lu_unpack_backward` accepts either.
    """

    @staticmethod
    def forward(ctx, LU_data, LU_pivots, unpack_data=True, unpack_pivots=True):
        ctx.lu_shape = (LU_data.shape[-2], LU_data.shape[-1])
        P, L, U = lu_unpack(LU_data, LU_pivots, unpack_data, unpack_pivots)
        ctx.mark_non_differentiable(P)
        return P, L, U

    @staticmethod
    def backward(ctx, grad_P, grad_L, grad_U):
        m, n = ctx.lu_shape
        return lu_unpack_backward(grad_L, grad_U, m, n), None, None, None


def _lu_unpack_autograd(LU_data, LU_pivots, unpack_data=True, unpack_pivots=True):
    """Differentiable `aten::lu_unpack` entry registered at the Autograd key.

    ``flag_gems.lu_unpack`` stays the forward-only kernel entry (and the device
    dispatch of ``aten::lu_unpack``); this wrapper is bound to the Autograd
    dispatch key so ``torch.lu_unpack`` records a graph whose backward is the
    fused :func:`lu_unpack_backward` kernel.
    """
    logger.debug("GEMS LU_UNPACK_AUTOGRAD")
    return LuUnpackFunction.apply(LU_data, LU_pivots, unpack_data, unpack_pivots)


def lu_unpack_out(
    LU_data, LU_pivots, unpack_data=True, unpack_pivots=True, *, P=None, L=None, U=None
):
    """
    Out-of-place variant of lu_unpack that writes results into pre-allocated tensors.

    Args:
        LU_data: Tensor of shape (..., m, n) containing the packed LU factorization
        LU_pivots: Tensor of shape (..., min(m, n)) containing the pivots (1-indexed)
        unpack_data: If True, unpack L and U. If False, return empty tensors.
        unpack_pivots: If True, unpack P. If False, return empty tensor.
        P: Optional pre-allocated output tensor for permutation matrix
        L: Optional pre-allocated output tensor for lower triangular matrix
        U: Optional pre-allocated output tensor for upper triangular matrix

    Returns:
        Tuple of (P, L, U)
    """
    P_result, L_result, U_result = lu_unpack(
        LU_data, LU_pivots, unpack_data, unpack_pivots
    )

    if P is not None and P_result.numel() > 0:
        P.copy_(P_result)
    else:
        P = P_result

    if L is not None and L_result.numel() > 0:
        L.copy_(L_result)
    else:
        L = L_result

    if U is not None and U_result.numel() > 0:
        U.copy_(U_result)
    else:
        U = U_result

    return (P, L, U)


@libentry()
@triton.jit
def lu_unpack_grad_kernel(
    grad_l_ptr,
    grad_u_ptr,
    grad_lu_ptr,
    m,
    n,
    HAS_L: tl.constexpr,
    HAS_U: tl.constexpr,
    BLOCK_M: tl.constexpr,
    BLOCK_N: tl.constexpr,
):
    """Repack ``grad_L`` / ``grad_U`` into the packed ``grad_LU`` layout.

    Grid: ``(batch, cdiv(m, BLOCK_M), cdiv(n, BLOCK_N))``.  The three tensors
    are contiguous, so the offsets follow from ``m``, ``n`` and
    ``k = min(m, n)`` without passing strides.

    ``L``'s strict lower triangle and ``U``'s closed upper triangle have
    disjoint supports inside the ``k x k`` square, so every ATen branch is one
    masked pass over the ``(..., m, n)`` packed result:

    * ``HAS_L and HAS_U``: the strict lower tile comes from ``grad_L``, the
      closed upper tile (diagonal included) from ``grad_U``; rows ``>= k``
      (only reachable when ``m > n``) are copied straight out of ``grad_L`` and
      columns ``>= k`` (only reachable when ``m < n``) out of ``grad_U``;
    * ``HAS_L`` only: ``tril(grad_L, -1)`` zero-padded to ``(..., m, n)``;
    * ``HAS_U`` only: ``triu(grad_U)`` zero-padded to ``(..., m, n)``.

    Each position is therefore at most one real value plus an exact ``0.0``,
    so the repack is bit-exact for every supported dtype.
    """

    batch_id = tl.program_id(0)
    pid_m = tl.program_id(1)
    pid_n = tl.program_id(2)

    k = tl.minimum(m, n)
    rows = pid_m * BLOCK_M + tl.arange(0, BLOCK_M)
    cols = pid_n * BLOCK_N + tl.arange(0, BLOCK_N)
    row_out = rows[:, None]
    col_out = cols[None, :]
    in_tile = (row_out < m) & (col_out < n)

    # 64-bit batch bases: a packed gradient can exceed 2**31 elements, and the
    # trailing-dimension offsets are the same either way.
    batch = batch_id.to(tl.int64)
    l_ptr = (
        grad_l_ptr
        + batch * tl.cast(m, tl.int64) * tl.cast(k, tl.int64)
        + row_out * k
        + col_out
    )
    u_ptr = (
        grad_u_ptr
        + batch * tl.cast(k, tl.int64) * tl.cast(n, tl.int64)
        + row_out * n
        + col_out
    )

    if HAS_L and HAS_U:
        l_mask = in_tile & (
            ((row_out < k) & (col_out < k) & (row_out > col_out)) | (row_out >= k)
        )
        u_mask = in_tile & (
            ((row_out < k) & (col_out < k) & (row_out <= col_out)) | (col_out >= k)
        )
        value = tl.load(l_ptr, mask=l_mask, other=0.0) + tl.load(
            u_ptr, mask=u_mask, other=0.0
        )
    elif HAS_L:
        l_mask = in_tile & (col_out < k) & (row_out > col_out)
        value = tl.load(l_ptr, mask=l_mask, other=0.0)
    elif HAS_U:
        u_mask = in_tile & (row_out < k) & (row_out <= col_out)
        value = tl.load(u_ptr, mask=u_mask, other=0.0)
    else:
        value = tl.zeros((BLOCK_M, BLOCK_N), dtype=tl.float32)

    tl.store(
        grad_lu_ptr
        + batch * tl.cast(m, tl.int64) * tl.cast(n, tl.int64)
        + row_out * n
        + col_out,
        value,
        mask=in_tile,
    )


# (m, n, numel, element_size) -> launch geometry.  The heuristic is a pure
# function of the workload, so caching it only removes per-call Python work.
_LAUNCH_PLAN_CACHE = {}


def _launch_plan(m, n, numel, element_size):
    """Tile geometry and warp count for one packed-gradient shape.

    The largest shapes run at the DRAM roofline: a long contiguous column span
    per CTA keeps the predicated loads coalesced (512 columns for float32 and
    256 for the wider float64 rows).  Smaller footprints need CTA-level
    parallelism instead, so the elements per CTA and the warp count shrink; the
    smallest shapes use single-warp CTAs where the launch cost dominates.
    """
    cells = m * n
    if cells <= 4096:
        target, col_cap, warps = 256, 256, 1
    elif cells <= 65536:
        target, col_cap, warps = (2048, 256, 4) if element_size >= 8 else (1024, 256, 2)
    elif element_size >= 8:
        target, col_cap, warps = 4096, 256, 4
    else:
        target, col_cap, warps = 4096, 512, 4

    block_n = min(triton.next_power_of_2(max(n, 1)), col_cap)
    block_m = min(triton.next_power_of_2(max(m, 1)), max(1, target // block_n))
    if warps == 2 and block_m * block_n > 1024:
        warps = 4
    return block_m, block_n, warps


def lu_unpack_backward(grad_L, grad_U, m, n):
    """Gradient of :func:`lu_unpack` with respect to the packed ``LU_data``.

    Mirrors ``lu_unpack_backward`` in ``torch/csrc/autograd/FunctionsManual``:
    the packed gradient of an ``(..., m, n)`` factorization is built from
    ``grad_L`` (``(..., m, k)``) and ``grad_U`` (``(..., k, n)``), where
    ``k = min(m, n)``.  Either argument may be ``None`` when only the other
    unpacked matrix took part in the graph; a supplied but zero-element
    gradient (a zero-size batch) yields a zero-element ``(..., m, n)`` result.

    ``LU_pivots`` and ``P`` are not differentiable, so they have no gradient.
    """
    # A 1-D empty tensor is the placeholder returned by ``unpack_data=False``,
    # i.e. an unused output rather than a zero-size matrix.
    has_l = grad_L is not None and grad_L.dim() >= 2
    has_u = grad_U is not None and grad_U.dim() >= 2
    if not (has_l or has_u):
        return None

    m = int(m)
    n = int(n)
    k = min(m, n)
    if has_l and tuple(grad_L.shape[-2:]) != (m, k):
        raise RuntimeError(
            f"lu_unpack_backward: grad_L must end with ({m}, {k}), "
            f"got {tuple(grad_L.shape)}"
        )
    if has_u and tuple(grad_U.shape[-2:]) != (k, n):
        raise RuntimeError(
            f"lu_unpack_backward: grad_U must end with ({k}, {n}), "
            f"got {tuple(grad_U.shape)}"
        )

    source = grad_L if has_l else grad_U
    grad_lu = torch.empty(
        source.shape[:-2] + (m, n), dtype=source.dtype, device=source.device
    )
    numel = grad_lu.numel()
    if numel == 0:
        return grad_lu

    # The kernel derives its offsets from `m` / `n` alone, so the inputs must be
    # contiguous; the autograd-produced gradients already are, so the copy is a
    # rare fallback for exotic strides.
    if has_l and not grad_L.is_contiguous():
        grad_L = grad_L.contiguous()
    if has_u and not grad_U.is_contiguous():
        grad_U = grad_U.contiguous()

    plan_key = (m, n, numel, source.element_size())
    plan = _LAUNCH_PLAN_CACHE.get(plan_key)
    if plan is None:
        block_m, block_n, num_warps = _launch_plan(m, n, numel, source.element_size())
        plan = (
            (numel // (m * n), triton.cdiv(m, block_m), triton.cdiv(n, block_n)),
            block_m,
            block_n,
            num_warps,
        )
        _LAUNCH_PLAN_CACHE[plan_key] = plan
    grid, block_m, block_n, num_warps = plan

    with torch_device_fn.device(source.device):
        lu_unpack_grad_kernel[grid](
            grad_L if has_l else grad_U,
            grad_U if has_u else grad_L,
            grad_lu,
            m,
            n,
            HAS_L=has_l,
            HAS_U=has_u,
            BLOCK_M=block_m,
            BLOCK_N=block_n,
            num_warps=num_warps,
        )
    return grad_lu
